-- Google Play Billing catalog (hand-maintained; not generated by `game-db import`).
-- Every product_id must also exist in Play Console with the same id:
--   consumables  -> Monetize > Products > In-app products (one-time, consumable)
--   subscription -> Monetize > Products > Subscriptions (base plans: monthly, yearly)
-- Prices are set in Play Console only. To retire a product set active = false;
-- never delete a row that purchases reference.
INSERT INTO billing_products (product_id, kind, title, coins, gems, active, sort_order) VALUES
    ('coins_500',  'consumable',   '500 Coins',   500, 0, true, 1),
    ('coins_1200', 'consumable',   '1,200 Coins', 1200, 0, true, 2),
    ('coins_3000', 'consumable',   '3,000 Coins', 3000, 0, true, 3),
    ('gems_50',    'consumable',   '50 Gems',     0, 50, true, 4),
    ('gems_150',   'consumable',   '150 Gems',    0, 150, true, 5),
    ('premium',    'subscription', 'SkillVerse Premium', 0, 0, true, 10)
ON CONFLICT (product_id) DO UPDATE SET
    kind = EXCLUDED.kind, title = EXCLUDED.title, coins = EXCLUDED.coins, gems = EXCLUDED.gems,
    active = EXCLUDED.active, sort_order = EXCLUDED.sort_order;
